#!/usr/bin/env python3
"""SPYDER v4: generate all public pages from one shared, trilingual source."""
from pathlib import Path
from html import escape as e
import xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1]; SITE=ROOT/'site'
def t(en,ru,uz,tag='span',attrs=''):
    return f'<{tag} data-en="{e(en,quote=True)}" data-ru="{e(ru,quote=True)}" data-uz="{e(uz,quote=True)}" {attrs}>{e(en)}</{tag}>'
def link(url,en,ru,uz,cls='btn'):
    return f'<a class="{cls}" href="{url}">{t(en,ru,uz)}</a>'
def eyebrow(en,ru,uz):return t(en,ru,uz,'p','class="eyebrow"')
def heading(en,ru,uz):return t(en,ru,uz,'h2')
def para(en,ru,uz,cls='lead'):return t(en,ru,uz,'p',f'class="{cls}"')
def icon(name):
    paths={'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>','chat':'<path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-6 4V6a2 2 0 0 1 2-2Z"/><path d="M7 9h10M7 13h6"/>','wallet':'<path d="M20 8V5H5a2 2 0 0 0-2 2v12h18V8H5a1 1 0 0 1 0-2"/><path d="M21 12h-6v4h6"/>','check':'<path d="m5 12 4 4L19 6"/>','shield':'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 11 3 3 5-5"/>','plus':'<path d="M12 5v14M5 12h14"/>','globe':'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-5 6-5 12 0 18 5-6 5-12 0-18Z"/>'}
    return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths[name]}</svg>'
def brand():return '<a class="brand" href="/"><img src="/assets/spyder-symbol-white.png" width="28" height="30" alt=""/><span>spyder<span class="brand-sub">wallet</span></span></a>'
